#include <iostream>
#include <stack>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long s;
    string ops;
    cin >> n >> s >> ops;
    const long long LIMIT = 1000000000000LL;
    stack<char> pending;
    for (char ch : ops) {
        if (ch == 'U') {
            if (!pending.empty()) {
                pending.pop();
            } else if (s > 1) {
                s /= 2;
            }
        } else {
            if (s > LIMIT / 2) {
                pending.push(ch);
            } else {
                s = (ch == 'L') ? s * 2 : s * 2 + 1;
            }
        }
    }
    cout << s << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    long long x;
    cin >> n >> m >> x;
    vector<pair<long long, long long>> stations(n);
    for (auto &s : stations) cin >> s.first >> s.second;
    sort(stations.begin(), stations.end());

    vector<pair<long long, int>> neg, pos;
    long long fixedPart = 0;
    for (int i = 0; i < m; ++i) {
        long long a, b;
        cin >> a >> b;
        fixedPart += 2 * x * b;
        if (a >= b) pos.push_back({a - b, i});
        else neg.push_back({a - b, i});
    }
    sort(pos.begin(), pos.end(), [](const auto &l, const auto &r) {
        return l.first > r.first;
    });
    sort(neg.begin(), neg.end());

    long long variablePart = 0;
    vector<long long> remaining(n);
    for (int i = 0; i < n; ++i) remaining[i] = stations[i].second;
    int l = 0, r = n - 1;
    for (auto &t : neg) {
        while (r >= 0 && remaining[r] == 0) --r;
        variablePart += 2 * stations[r].first * t.first;
        --remaining[r];
    }
    for (auto &t : pos) {
        while (l < n && remaining[l] == 0) ++l;
        variablePart += 2 * stations[l].first * t.first;
        --remaining[l];
    }
    cout << fixedPart + variablePart << '\n';
    return 0;
}
